modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.ParallelResonance;
end Baseline;
model BUG004
  extends Modelica.Electrical.Analog.Examples.ParallelResonance(inductor1(L=0));
end BUG004;
model BUG005
  extends Modelica.Electrical.Analog.Examples.ParallelResonance(inductor2(L=0));
end BUG005;
model BUG008
  extends Modelica.Electrical.Analog.Examples.ParallelResonance(capacitor1(C=0));
end BUG008;
model BUG009
  extends Modelica.Electrical.Analog.Examples.ParallelResonance(capacitor2(C=0));
end BUG009;
model FinalBUG004
  extends Modelica.Electrical.Analog.Examples.ParallelResonance(inductor1(final L=0));
end FinalBUG004;
model FinalBUG005
  extends Modelica.Electrical.Analog.Examples.ParallelResonance(inductor2(final L=0));
end FinalBUG005;
model FinalBUG008
  extends Modelica.Electrical.Analog.Examples.ParallelResonance(capacitor1(final C=0));
end FinalBUG008;
model FinalBUG009
  extends Modelica.Electrical.Analog.Examples.ParallelResonance(capacitor2(final C=0));
end FinalBUG009;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG004\n");
simulate(BUG004, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG005\n");
simulate(BUG005, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG008\n");
simulate(BUG008, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG009\n");
simulate(BUG009, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG004\n");
simulate(FinalBUG004, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG005\n");
simulate(FinalBUG005, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG008\n");
simulate(FinalBUG008, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG009\n");
simulate(FinalBUG009, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE BUG004\n");
system("./Baseline -override inductor1.L=0 -r=BUG004_override.csv");
print("AUDIT_OVERRIDE BUG005\n");
system("./Baseline -override inductor2.L=0 -r=BUG005_override.csv");
print("AUDIT_OVERRIDE BUG008\n");
system("./Baseline -override capacitor1.C=0 -r=BUG008_override.csv");
print("AUDIT_OVERRIDE BUG009\n");
system("./Baseline -override capacitor2.C=0 -r=BUG009_override.csv");
